<?php /* VIVA NOTE: One room form handles create/edit; rent and detail edit windows differ. */ $editing=(bool)$room;$id=$editing?(int)$room['room_id']:0;$detailsOpen=(!$editing||(bool)$windows['details_open']);$rentOpen=(!$editing||(bool)$windows['rent_open']); ?>
<div class="toolbar"><p>Room details are editable for 15 minutes. Rent follows an annual lock after the initial window.</p><a href="<?=e(url('/rooms'))?>">← Rooms</a></div>
<form method="post" action="<?=e(url($editing?'/room/update':'/room/save',$editing?['id'=>$id]:[]))?>" class="panel form-panel"><?=csrf_field()?>
<?php if(!$editing):?><label class="full">Property<select name="property_id" required><?php foreach($properties as $p):?><option value="<?=e($p['property_id'])?>"><?=e($p['title'])?></option><?php endforeach;?></select></label><?php endif;?>
<?php if(!$detailsOpen):?><div class="alert warning">Room details are locked. Rent may still be edited when its lock expires.</div><?php endif;?>
<div class="form-grid">
<label>Room label<input name="label" maxlength="100" required value="<?=e($room['room_label']??'')?>" <?=$detailsOpen?'':'readonly'?>></label>
<label>Type<select name="type" <?=$detailsOpen?'':'disabled'?>><?php foreach(['single','shared'] as $v):?><option value="<?=e($v)?>" <?=($room['room_type']??'single')===$v?'selected':''?>><?=e(pill($v))?></option><?php endforeach;?></select><?php if(!$detailsOpen):?><input type="hidden" name="type" value="<?=e($room['room_type'])?>"><?php endif;?></label>
<label>Capacity<input name="capacity" type="number" min="1" max="100" value="<?=e($room['slot_capacity']??1)?>" <?=$detailsOpen?'':'readonly'?> required></label>
<label>Rent (LKR/month)<input name="price" type="number" min="1" step="0.01" value="<?=e($room['price']??'')?>" <?=$rentOpen?'':'readonly'?> required></label>
<label>Deposit (LKR)<input name="deposit" type="number" min="0" step="0.01" value="<?=e($room['deposit_amount']??0)?>" <?=$detailsOpen?'':'readonly'?> required></label>
<label>Furnishing<select name="furnishing" <?=$detailsOpen?'':'disabled'?>><?php foreach(['unfurnished','semi_furnished','furnished'] as $v):?><option value="<?=e($v)?>" <?=($room['furnishing']??'unfurnished')===$v?'selected':''?>><?=e(pill($v))?></option><?php endforeach;?></select><?php if(!$detailsOpen):?><input type="hidden" name="furnishing" value="<?=e($room['furnishing'])?>"><?php endif;?></label>
<label>Gender preference<select name="gender" <?=$detailsOpen?'':'disabled'?>><?php foreach(['any','male','female'] as $v):?><option value="<?=e($v)?>" <?=($room['gender_preference']??'any')===$v?'selected':''?>><?=e(pill($v))?></option><?php endforeach;?></select><?php if(!$detailsOpen):?><input type="hidden" name="gender" value="<?=e($room['gender_preference'])?>"><?php endif;?></label>
<label class="check-row"><input type="checkbox" name="partial" value="1" <?=!empty($room['partial_occupancy_allowed'])?'checked':''?> <?=$detailsOpen?'':'disabled'?>> Allow partial occupancy<?php if(!$detailsOpen):?><input type="hidden" name="partial" value="<?=e($room['partial_occupancy_allowed'])?>"><?php endif;?></label>
<label class="full">House rules<textarea name="rules" maxlength="3000" rows="4" <?=$detailsOpen?'':'readonly'?>><?=e($room['house_rules']??'')?></textarea></label></div>
<?php if($detailsOpen||$rentOpen):?><div class="form-actions"><button class="btn"><?= $editing?'Save allowed changes':'Create room' ?></button><a class="btn secondary" href="<?=e(url('/rooms'))?>">Cancel</a></div><?php else:?><div class="alert warning">Neither normal details nor rent can currently be changed.</div><?php endif;?></form>
